#include <cstdio>

const int N = 2000;
const int MOD = 1000000007;

int n, f[N + 5][N + 5];

int main() {
    scanf("%d", &n);
    n *= 2;

    f[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= n; ++j) {
            if (j >= 1)
                f[i][j] = (f[i][j] + f[i - 1][j - 1]) % MOD;
            f[i][j] = (f[i][j] + f[i - 1][j + 1]) % MOD;
        }
    }

    printf("%d\n", f[n][0]);
    return 0;
}

